<?php
// Analytics staging installer, DATABASE-FREE static checks: the optional/empty-table migrations are additive and idempotent, nothing can be dropped or copied, the five-column shape is exact,
// MySQL 8.4 compatibility rules (no removed syntax, case-insensitive information_schema keys), and the installer's safety design.
$root = dirname(__DIR__); $pass = 0; $fail = 0; function ok($c, string $m): void { global $pass, $fail; if ($c) $pass++; else { $fail++; fwrite(STDERR, "  FAIL: $m\n"); } }
$strip = fn(string $s) => preg_replace('#/\*.*?\*/#s', '', preg_replace('/^\s*--.*$/m', '', $s));
$dir = $root . '/database/analytics_install'; $files = glob($dir . '/*.sql'); $names = array_map('basename', $files);
foreach (['00_preflight_readonly.sql', '00_preflight_readonly_no_tool_clicks.sql', '01_page_views.sql', '02_events.sql', '03_tool_clicks_if_missing.sql', '04_tool_votes_if_missing_OPTIONAL.sql', '90_verify_readonly.sql', '99_rollback_reporting.sql', '99_rollback_raw_tables.sql'] as $f) ok(in_array($f, $names, true), "$f exists");
foreach (['01_page_views.sql', '02_events.sql', '03_tool_clicks_if_missing.sql', '04_tool_votes_if_missing_OPTIONAL.sql'] as $f) { $c = str_ireplace('ON UPDATE CURRENT_TIMESTAMP', '', $strip(file_get_contents("$dir/$f"))); ok(preg_match_all('/^\s*CREATE TABLE IF NOT EXISTS/mi', $c) === 1 && !preg_match('/\b(DROP|TRUNCATE|DELETE|UPDATE|ALTER|INSERT|REPLACE|GRANT|REVOKE|RENAME)\b/i', $c) && !preg_match('/CREATE TABLE(?! IF NOT EXISTS)/i', $c), "$f: one CREATE TABLE IF NOT EXISTS and nothing else (additive, idempotent, no data movement)"); }
foreach (['00_preflight_readonly.sql', '00_preflight_readonly_no_tool_clicks.sql', '90_verify_readonly.sql'] as $f) ok(!preg_match('/^\s*(CREATE|DROP|TRUNCATE|DELETE|UPDATE|ALTER|INSERT|REPLACE|GRANT|REVOKE)\b/mi', $strip(file_get_contents("$dir/$f"))), "$f is read-only");
$tc = $strip(file_get_contents("$dir/03_tool_clicks_if_missing.sql")); preg_match('/\((.*)\)\s*ENGINE/s', $tc, $m); $cols = []; foreach (preg_split('/,\s*\n/', $m[1] ?? '') as $line) if (preg_match('/^\s*([a-z_]+)\s+(INT|VARCHAR|CHAR|TIMESTAMP)/i', $line, $mm)) $cols[] = $mm[1];
ok($cols === ['id', 'tool_slug', 'visitor_id', 'ip_hash', 'created_at'], 'tool_clicks is created with exactly the five production columns');
ok(!preg_match('/UNIQUE/i', $tc) && preg_match('/visitor_id VARCHAR\(64\) DEFAULT NULL/', $tc) && preg_match('/ip_hash CHAR\(64\) DEFAULT NULL/', $tc), 'no unique index; identifier columns are NULL-able (the privacy-fixed recorder writes empty strings)');
ok(trim(file_get_contents($root . '/tests/fixtures/interactions_current.sql')) !== '' && strpos(file_get_contents($root . '/tests/fixtures/interactions_current.sql'), 'visitor_id VARCHAR(64) DEFAULT NULL') !== false, 'the definition matches the repository fixture of the current shape');
ok(!preg_match('/tool_clicks/', $strip(file_get_contents("$dir/00_preflight_readonly_no_tool_clicks.sql")) === '' ? '' : preg_replace("/'[^']*'/", '', $strip(file_get_contents("$dir/00_preflight_readonly_no_tool_clicks.sql")))), 'the no-tool_clicks preflight never queries the table (only names it inside the information_schema list)');
foreach ($names as $f) { $c = $strip(file_get_contents("$dir/$f")); ok(!preg_match('/tool_clicks\b/i', preg_replace('/^(?!.*(DROP|TRUNCATE|DELETE|UPDATE|ALTER)).*$/mi', '', $c)) || $f === '03_tool_clicks_if_missing.sql', "$f never drops, truncates, deletes from, updates or alters tool_clicks"); }
// MySQL 8.4 compatibility rules
$all = ''; foreach ($files as $f) $all .= $strip(file_get_contents($f)); ok(!preg_match('/\bPASSWORD\(|NO_AUTO_CREATE_USER|SQL_CALC_FOUND_ROWS|\bGROUP BY .* (ASC|DESC)\b|utf8mb3|latin1|ENGINE=MyISAM|\bMASTER_/i', $all), 'SQL files use no syntax removed or deprecated in MySQL 8.4');
ok(preg_match('/ENGINE=InnoDB/', file_get_contents("$dir/03_tool_clicks_if_missing.sql")) === 1 && strpos(file_get_contents("$dir/03_tool_clicks_if_missing.sql"), 'utf8mb4') !== false, 'InnoDB and utf8mb4 (MySQL 8.4 defaults)');
$v = file_get_contents($root . '/scripts/analytics_verify.php'); ok(strpos($v, 'array_change_key_case') !== false && strpos($v, 'MySQL 8 returns information_schema column labels in UPPER case') !== false && strpos($v, 'column_name AS column_name') !== false, 'the verifier tolerates MySQL 8 upper-case information_schema labels');
ok(strpos($v, '--allow-missing-tool-clicks') !== false && strpos($v, "'tool_clicks table exists', 'missing'") !== false, 'the verifier allows a missing tool_clicks only before installation and only when told');
$all2 = ''; foreach (['adm_an2_store.php', 'adm_analytics.php', 'analytics.php', 'analytics_retention.php', 'helpers.php'] as $f) $all2 .= file_get_contents($root . '/' . $f); ok(!preg_match('/\$\w+\[[\'"](column_name|table_name|index_name)[\'"]\]/', $all2), 'application code does not index information_schema results by lower-case label');
// installer design
$sh = file_get_contents($root . '/scripts/analytics_staging_install.sh'); $code = preg_replace('/^\s*#.*$/m', '', $sh);
ok(strpos($sh, 'DB=aihub_phase6_test') !== false && strpos($sh, 'set -euo pipefail') !== false, 'target database hard-coded; strict shell mode');
ok(strpos($sh, '03_tool_clicks_if_missing.sql') !== false && strpos($sh, '00_preflight_readonly_no_tool_clicks.sql') !== false && strpos($sh, '--create-tool-votes') !== false && strpos($sh, '--allow-missing-tool-clicks') !== false, 'installer supports a staging database without click data, with an explicit optional tool_votes flag');
ok(strpos($sh, 'CONFIRM_INSTALL') !== false && strpos($sh, 'ALLOW_SHARED_SERVER') !== false && strpos($sh, 'privileges that reach production') !== false, 'apply needs a confirmation variable; shared-server and production-reaching accounts are refused');
ok(strpos($sh, '--set-gtid-purged=OFF') !== false && strpos($sh, '--no-tablespaces') !== false && strpos($sh, 'retrying without them') !== false, 'dump options handle MySQL 8.4 (no GTID statements, no tablespace privilege, routine privilege fallback)');
ok(!preg_match('/\b(DROP\s+TABLE|TRUNCATE|DELETE\s+FROM|UPDATE\s+\w+\s+SET|ALTER\s+TABLE)\b/i', $code) && count(array_filter(explode("\n", $code), fn($l) => strpos($l, 'DROP DATABASE') !== false && strpos($l, '$SCR') === false)) === 0 && strpos($code, 'SCR=${DB}_bkverify_') !== false, 'the only DROP statements in the installer drop its own throw-away restore-test scratch database');
ok(strpos($sh, 'counts-before.txt') !== false && strpos($sh, 'counts-after.txt') !== false && strpos($sh, 'counts-restored.txt') !== false, 'row counts of every existing table are recorded before, after and in the restored copy');
ok(strpos($sh, 'production') !== false && !preg_match('/mysqldump[^\n]*\$PROD|-D\s*\$PROD|\$PROD\.tool_clicks/', $code), 'the installer never dumps or reads production');
echo "$pass passed, $fail failed\n"; exit($fail ? 1 : 0);
